  'With Firebase OTP enabled, verification codes will be sent through Firebase.' => 'مع تمكين Firebase OTP ، سيتم إرسال رموز التحقق من خلال Firebase.',
  'Enable Firebase OTP means users will not receive verification codes through Email or SMS Although those methods are activated.' => 'تمكين Firebase OTP يعني أن المستخدمين لن يتلقوا رموز التحقق من خلال البريد الإلكتروني أو الرسائل القصيرة على الرغم من تنشيط هذه الطرق.',
  'If you disable Firebase OTP, users will no longer receive verification codes via Firebase. You must activate Email or SMS verification as an alternative' => 'إذا قمت بتعطيل Firebase OTP ، فلن يتلقى المستخدمون رموز التحقق عبر Firebase. ',
