  'If you are activating social login as the login method, you must enable at least one option between Google, Facebook & Apple.' => 'إذا كنت تقوم بتنشيط تسجيل الدخول الاجتماعي كطريقة تسجيل الدخول ، فيجب عليك تمكين خيار واحد على الأقل بين Google و Facebook & Apple.',
  'By enabling manual login, customers will get the option to create an account and log in using the necessary credentials & password in the app & website' => 'من خلال تمكين تسجيل الدخول اليدوي ، سيحصل العملاء على خيار إنشاء حساب وتسجيل الدخول باستخدام بيانات الاعتماد وكلمة المرور اللازمة في التطبيق والموقع',
  'With OTP Login, customers can log in using their phone number. while new customers can create accounts instantly.' => 'مع تسجيل الدخول إلى OTP ، يمكن للعملاء تسجيل الدخول باستخدام رقم هاتفهم. ',
  'With Social Login, customers can log in using social media credentials. while new customers can create accounts instantly.' => 'مع تسجيل الدخول الاجتماعي ، يمكن للعملاء تسجيل الدخول باستخدام بيانات اعتماد وسائل التواصل الاجتماعي. ',
  'Enabling Google Login, customers can log in to the site using their existing Gmail credentials.' => 'تمكين تسجيل الدخول إلى Google ، يمكن للعملاء تسجيل الدخول إلى الموقع باستخدام بيانات اعتماد Gmail الحالية.',
  'Enabling Facebook Login, customers can log in to the site using their existing Facebook credentials' => 'تمكين تسجيل الدخول على Facebook ، يمكن للعملاء تسجيل الدخول إلى الموقع باستخدام بيانات اعتماد Facebook الحالية الخاصة بهم',
  'Enabling Apple Login, customers can log in to the site using their existing Apple login credentials, Only for Apple devices' => 'تمكين تسجيل الدخول إلى Apple ، يمكن للعملاء تسجيل الدخول إلى الموقع باستخدام بيانات اعتماد تسجيل الدخول إلى Apple الحالية ، فقط لأجهزة Apple',
  'If Email verification is on, Customers must verify their email address with an OTP to complete the signup process.' => 'إذا كان التحقق من البريد الإلكتروني قيد التشغيل ، يجب على العملاء التحقق من عنوان بريدهم الإلكتروني باستخدام OTP لإكمال عملية الاشتراك.',
